// HasCapability applies the HasEdge predicate on the "capability" edge.
func HasCapability() predicate.Feature {
	return predicate.Feature(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CapabilityTable, CapabilityColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCapabilityWith applies the HasEdge predicate on the "capability" edge with a given conditions (other predicates).
func HasCapabilityWith(preds ...predicate.Capability) predicate.Feature {
	return predicate.Feature(func(s *sql.Selector) {
		step := newCapabilityStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

